import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/ViewSales.css";

const ViewSales = () => {
  const userId = sessionStorage.getItem("userId");
  const [sales, setSales] = useState([]);
  const [payoutTotal, setPayoutTotal] = useState(0);
  const [paidAmount, setPaidAmount] = useState(null);

  useEffect(() => {
    const fetchSales = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/sales/${userId}`);
        const data = await res.json();
        setSales(data);
        const total = data.reduce((sum, sale) => sum + parseFloat(sale.price || 0), 0);
        setPayoutTotal(total);
      } catch (err) {
        console.error("Failed to load sales:", err);
      }
    };
    fetchSales();
  }, [userId]);

  const handlePayout = () => {
    const payout = (payoutTotal * 0.95).toFixed(2); // 5% fee
    setPaidAmount(payout);
    setPayoutTotal(0);
  };

  const markAsReviewed = async (saleId) => {
    try {
      await fetch(`${API_BASE_URL}/api/sales/${saleId}/reviewed`, { method: "PUT" });
      setSales((prev) =>
        prev.map((s) => (s.id === saleId ? { ...s, reviewed: true } : s))
      );
    } catch (err) {
      console.error("Failed to mark as reviewed:", err);
    }
  };

  const deleteSale = async (saleId) => {
    const confirmDelete = window.confirm("Are you sure you want to delete this sale?");
    if (!confirmDelete) return;

    try {
      await fetch(`${API_BASE_URL}/api/sales/${saleId}`, { method: "DELETE" });
      setSales((prev) => prev.filter((s) => s.id !== saleId));
    } catch (err) {
      console.error("Failed to delete sale:", err);
    }
  };

  return (
    <>
      <Navbar />
      <div className="viewsales-container">
        <h2 className="viewsales-heading">💼 Sales Dashboard</h2>

        {sales.length === 0 ? (
          <p className="viewsales-empty">You haven't made any sales yet.</p>
        ) : (
          <div className="viewsales-list">
            {sales.map((sale) => (
              <div key={sale.id} className="viewsales-card">
                <img src={sale.image} alt={sale.title} className="viewsales-image" />
                <div className="viewsales-info">
                  <h4>{sale.title}</h4>
                  <p><strong>Listing ID:</strong> #{sale.listing_id}</p>
                  <p><strong>Sold For:</strong> ${parseFloat(sale.price).toFixed(2)}</p>
                  <p><strong>Date:</strong> {new Date(sale.created_at).toLocaleDateString()}</p>
                  <p><strong>Reviewed:</strong> {sale.reviewed ? "✅ Yes" : "❌ No"}</p>

                  {!sale.reviewed && (
                    <button onClick={() => markAsReviewed(sale.id)} className="mark-reviewed-btn">
                      ✅ Mark as Reviewed
                    </button>
                  )}
                  <button onClick={() => deleteSale(sale.id)} className="delete-sale-btn">
                    🗑️ Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        <div className="viewsales-payout">
          <h3>Total Pending Payout: <span>${payoutTotal.toFixed(2)}</span></h3>
          {payoutTotal > 0 && (
            <button onClick={handlePayout} className="viewsales-payout-btn">
              💸 Payout Now (5% Fee)
            </button>
          )}
          {paidAmount && (
            <div className="viewsales-paid-alert">
              ✅ You got paid: <strong>${paidAmount}</strong> (after 5% fee)
            </div>
          )}
        </div>
      </div>
      <Footer />
    </>
  );
};

export default ViewSales;
